pipeline {
  agent none

  stages {
stage('Publish') {
  agent { label 'linux && release' }
  steps {
    checkout scm
    sh 'npm ci'
    sh 'npm run build'
    dir('release') {
withCredentials([file(credentialsId: 'registry-file', variable: 'PUBLISH_CONFIG')]) {
  sh "./scripts/publish.sh $PUBLISH_CONFIG"
  archiveArtifacts '*'
}
}
  }

}
  }
}

